def set_model(self, model):
    self.model = model
    if K.backend() == 'tensorflow':
        self.sess = K.get_session()

    if self.histogram_freq and self.merged is None:
        for layer in self.model.layers:
            for weight in layer.weights:
                mapped_weight_name = weight.name.replace(':', '_')
                tf.summary.histogram(mapped_weight_name, weight)

                if self.write_grads:
                    grads = model.optimizer.get_gradients(model.total_loss, weight)

                    def is_indexed_slices(grad):
                        return type(grad).__name__ == 'IndexedSlices'

                    grads = [
                        grad.values if is_indexed_slices(grad) else grad
                        for grad in grads
                    ]
                    tf.summary.histogram('{}_grad'.format(mapped_weight_name), grads)

                if self.write_images:
                    w_img = tf.squeeze(weight)
                    shape = K.int_shape(w_img)

                    # Handle weight images based on shape
                    if len(shape) == 2:  # Dense layer kernel case
                        if shape[0] > shape[1]:
                            w_img = tf.transpose(w_img)
                        w_img = tf.reshape(w_img, [1] + list(shape) + [1])
                    elif len(shape) == 3:  # Convnet case
                        if K.image_data_format() == 'channels_last':
                            w_img = tf.transpose(w_img, perm=[2, 0, 1])
                        w_img = tf.reshape(w_img, [shape[0], shape[1], shape[2], 1])
                    elif len(shape) == 1:  # Bias case
                        w_img = tf.reshape(w_img, [1, shape[0], 1, 1])
                    else:
                        continue  # Unsuitable dimension

                    shape = K.int_shape(w_img)
                    assert len(shape) == 4 and shape[-1] in [1, 3, 4], f"Image shape must be 4D with last dimension as 1, 3, or 4. Got: {shape}"
                    tf.summary.image(mapped_weight_name, w_img)

            if hasattr(layer, 'output'):
                if isinstance(layer.output, (list, tuple)):
                    for i, output in enumerate(layer.output):
                        tf.summary.histogram('{}_out_{}'.format(layer.name, i), output)
                else:
                    tf.summary.histogram('{}_out'.format(layer.name), layer.output)

    self.merged = tf.summary.merge_all()

    if self.write_graph:
        self.writer = tf.summary.FileWriter(self.log_dir, self.sess.graph)
    else:
        self.writer = tf.summary.FileWriter(self.log_dir)

    if self.embeddings_freq:
        embeddings_layer_names = self.embeddings_layer_names or [
            layer.name for layer in self.model.layers if type(layer).__name__ == 'Embedding'
        ]

        embeddings = {layer.name: layer.weights[0]
                      for layer in self.model.layers if layer.name in embeddings_layer_names}

        self.saver = tf.train.Saver(list(embeddings.values()))

        embeddings_metadata = (self.embeddings_metadata
                               if isinstance(self.embeddings_metadata, dict)
                               else {layer_name: self.embeddings_metadata for layer_name in embeddings.keys()})

        config = projector.ProjectorConfig()
        self.embeddings_ckpt_path = os.path.join(self.log_dir, 'keras_embedding.ckpt')

        for layer_name, tensor in embeddings.items():
            embedding = config.embeddings.add()
            embedding.tensor_name = tensor.name

            if layer_name in embeddings_metadata:
                embedding.metadata_path = embeddings_metadata[layer_name]

        projector.visualize_embeddings(self.writer, config)
